                    "sql": "CREATE OR REPLACE TABLE campaign_reports_summary AS ( WITH CTE AS ( SELECT COALESCE( TRY_TO_DATE(a.run_date, \'DD/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY/MM/DD\'), TRY_TO_DATE(a.RUN_DATE, \'D/M/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'D/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-M-D\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-MM-DD\'), TRY_TO_DATE(a.RUN_DATE, \'MM/DD/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'MM-DD-YYYY\') ) AS run_date, ROUND(a.CAMPAIGN_ID,0) AS campaign_id, a.CHANNEL AS channel, a.OS as OS, MAX(a.CAMPAIGN_NAME) AS campaign_name, MAX(a.LABELS) AS labels, MAX(CONCAT_WS(CHAR(10)||CHAR(10), a.TITLE, a.MESSAGE)) AS details, MAX(a.who_query) AS segment, SUM(TRY_TO_NUMBER(a.total_sent_users)) AS total_sent_users, SUM(TRY_TO_NUMBER(a.total_clicked_users)) AS total_clicked_users, SUM(TRY_TO_NUMBER(a.total_viewed_users)) AS total_viewed_users, SUM(TRY_TO_NUMBER(a.total_delivered_users)) AS total_delivered_users, SUM(TRY_TO_NUMBER(a.total_sent_events)) AS total_sent_events, SUM(TRY_TO_NUMBER(a.total_viewed_events)) AS total_viewed_events, SUM(TRY_TO_NUMBER(a.total_clicked_events)) AS total_clicked_events, SUM(TRY_TO_NUMBER(a.total_delivered_events)) AS total_delivered_events FROM snitch_db.maplemonk.CT_CLEVERTAP_DB a WHERE a.channel IN (\'Sms\',\'Push Notification\',\'WhatsApp\', \'Email\') AND a.Campaign_id NOT IN (\'1753099592\', \'1753100151\', \'1753100666\', \'1753175787\', \'1753101169\', \'1753101430\', \'1753253552\', \'1753254018\', \'1753254120\', \'1753339568\', \'1753339471\', \'1753264726\', \'1753957559\', \'1754053751\', \'1754053644\', \'1753350802\', \'1753351025\', \'1753356912\', \'1753356978\', \'1753256023\', \'1752834990\', \'1754053876\', \'1752136011\', \'1751022333\', \'1754054106\', \'1755008860\', \'1738771106\', \'1743780334\', \'1744023026\', \'1737203919\', \'1743826165\', \'1738829230\', \'1744024889\', \'1748166392\', \'1755065366\', \'17