\'), TRY_TO_DATE(a.RUN_DATE, \'MM/DD/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'MM-DD-YYYY\') ) AS run_date, ROUND(a.CAMPAIGN_ID,0) AS campaign_id, a.CHANNEL AS channel, a.OS as OS, MAX(a.CAMPAIGN_NAME) AS campaign_name, MAX(a.LABELS) AS labels, MAX(CONCAT_WS(CHAR(10)||CHAR(10), a.TITLE, a.MESSAGE)) AS details, MAX(a.who_query) AS segment, SUM(TRY_TO_NUMBER(a.total_sent_users)) AS total_sent_users, SUM(TRY_TO_NUMBER(a.total_clicked_users)) AS total_clicked_users, SUM(TRY_TO_NUMBER(a.total_viewed_users)) AS total_viewed_users, SUM(TRY_TO_NUMBER(a.total_delivered_users)) AS total_delivered_users, SUM(TRY_TO_NUMBER(a.total_sent_events)) AS total_sent_events, SUM(TRY_TO_NUMBER(a.total_viewed_events)) AS total_viewed_events, SUM(TRY_TO_NUMBER(a.total_clicked_events)) AS total_clicked_events, SUM(TRY_TO_NUMBER(a.total_delivered_events)) AS total_delivered_events FROM SNITCH_DB.MAPLEMONK.CT_CAMPAIGNS_JULY_AUG a WHERE a.channel IN (\'Sms\',\'Push Notification\',\'WhatsApp\', \'Email\') AND a.Campaign_id NOT IN (\'1753099592\', \'1753100151\', \'1753100666\', \'1753175787\', \'1753101169\', \'1753101430\', \'1753253552\', \'1753254018\', \'1753254120\', \'1753339568\', \'1753339471\', \'1753264726\', \'1753957559\', \'1754053751\', \'1754053644\', \'1753350802\', \'1753351025\', \'1753356912\', \'1753356978\', \'1753256023\', \'1752834990\', \'1754053876\', \'1752136011\', \'1751022333\', \'1754054106\', \'1755008860\', \'1738771106\', \'1743780334\', \'1744023026\', \'1737203919\', \'1743826165\', \'1738829230\', \'1744024889\', \'1748166392\', \'1755065366\', \'1740978249\', \'1753166642\', \'1739856954\', \'1741259483\', \'1743825958\', \'1746798665\', \'1743780087\', \'1747825397\', \'1746790020\', \'1738909183\', \'1746788998\', \'1747824886\', \'1741166678\', \'1741168362\', \'1744025425\', \'1737004843\', \'1737005227\', \'1743779275\', \'1743779146\', \'1744023956\', \'1737203875\', \'1743779011\', \'1746007871\', \'1743825792\', \'1744024451\', \'1739795074\', \'1738829398\', \'1741163643\', \'1744023687\', \'1744022795\', \'1744025675\', \'1737204081\', \'1758539978\', \'1758534671\', \'1743690450\',\'1737005227\',\'1737004843\',\'1738771106\',\'1747733352\',\'1754054106\',\'1738909183\',\'1741163643\',\'1741169554\',\'1737203875\',\'1755065366\',\'1744025675\',\'1744023687\',\'1756881109\',\'1746007871\',\'1753256023\',\'1748335275\',\'1752136011\',\'1737203919\',\'1751022333\',\'1737451837\',\'1744022795\',\'1752834990\',\'1757497135\',\'1747991124\',\'1737455242\',\'1748314470\',\'1744023956\',\'1744023026\',\'1741259483\',\'1744025425\',\'1752566537\',\'1738829398\',\'1744024889\',\'1748314237\',\'1747991231\',\'1738829230\',\'1752566342\',\'1740978249\',\'1737204081\',\'1748166392\',\'1757494030\',\'1756881276\',\'1753100666\',\'1753101430\',\'1753100151\',\'1753099592\',\'1753175787\',\'1753101169\',\'1748335426\',\'1755854795\',\'1757316145\',\'1757335073\',\'1755864962\',\'1755866984\',\'1756204044\',\'1755867459\',\'1756206729\',\'1756712942\',\'1757334839\') AND labels not ilike \'%customer support%\' and labels not ilike \'%offline%\' and labels not ilike \'%test%\' AND a.created_by NOT IN (\'lohith.r@snitch.com\', \'ashwin.k@snitch.co.in\', \'nandini.t@snitch.com\', \'lohith.r@snitch.com\') GROUP BY run_date, a.CAMPAIGN_ID, a.CHANNEL, a.OS ), marked AS ( SELECT campaign_id, channel, os, campaign_name, details, labels, run_date, DATE_TRUNC(\'week\', run_date) AS week_start, IFF(total_sent_events > 0, run_date, NULL) AS anchor_run_date, total_sent_users, total_clicked_users, total_viewed_users, total_delivered_users, total_sent_events, total_viewed_events, total_clicked_events, total_delivered_events FROM CTE ), anchor_days AS ( SELECT DISTINCT campaign_id, channel, os, week_start, anchor_run_date FROM marked WHERE anchor_run_date IS NOT NULL ), anchor_ranges AS ( SELECT campaign_id, channel, os, week_start, anchor_run_date AS range_start, COALESCE( LEAD(anchor_run_date) OVER ( PARTITION BY campaign_id, channel, week_start ORDER BY anchor_run_date ) - 1, anchor_run_date + 6 ) AS range_end FROM anchor_days ), coupon_codes AS ( SELECT campaign_id, details, run_date, channel, REGEXP_SUBSTR( details, \'(use[[:space:]]+code|coupon[[:space:]]*code|code)[[:space:]]*[-: ]?[[:space:]]*([A-Za-z0-9_-]{3,20})\', 1, 1, \'i\', 2 ) AS coupon_code_raw, CASE WHEN REGEXP_SUBSTR( details, \'(use[[:space:]]+code|coupon[[:space:]]*code|code)[[:space:]]*[-: ]?[[:space:]]*([A-Za-z0-9_-]{3,20})\', 1, 1, \'i\', 2 ) IS NOT NULL AND NOT REGEXP_LIKE(COALESCE(details,\'\'), \'\\$replacement\\$[[:space:]]*##w:\', \'i\') AND NOT ( COALESCE(details,\'\') ILIKE \'%unfinished%cart%\' OR COALESCE(details,\'\') ILIKE \'%abandon%\' OR COALESCE(details,\'\') ILIKE \'%abandoned%\' ) THEN UPPER(REGEXP_SUBSTR( details, \'(use[[:space:]]+code|coupon[[:space:]]*code|code)[[:space:]]*[-: ]?[[:space:]]*([A-Za-z0-9_-]{3,20})\', 1, 1, \'i\', 2 )) ELSE NULL END AS coupon_code FROM CTE ), codes_in_range AS ( SELECT ar.campaign_id, ar.channel, ar.os, ar.week_start, ar.range_start, MAX(c.coupon_code) AS coupon_code FROM anchor_ranges ar JOIN coupon_codes c ON c.campaign_id = ar.campaign_id AND c.channel = ar.channel AND c.run_date BETWEEN ar.range_start AND ar.range_end GROUP BY ar.campaign_id, ar.channel, ar.os, ar.week_start, ar.range_start ), coupon_codes_unique AS ( SELECT DISTINCT UPPER(coupon_code) AS coupon_code FROM coupon_codes WHERE coupon_code IS NOT NULL ), campaign_bucket_totals AS ( SELECT ar.campaign_id, ar.channel, ar.os, ar.week_start, ar.range_start AS correct_run_date, SUM(m.total_sent_events) AS total_sents, SUM(m.total_viewed_events) AS total_views, SUM(m.total_clicked_events) AS total_clicks, SUM(m.total_delivered_events) AS total_deliveries, SUM(m.total_sent_users) AS total_sent_users, SUM(m.total_viewed_users) AS total_viewed_users, SUM(m.total_clicked_users) AS total_clicked_users, SUM(m.total_delivered_users) AS total_delivered_users, MAX(m.campaign_name) AS campaign_name, MAX(m.details) AS details, MAX(m.labels) AS labels, MAX(cr.coupon_code) AS coupon_code FROM anchor_ranges ar JOIN marked m ON m.campaign_id = ar.campaign_id AND m.channel = ar.channel AND m.week_start = ar.week_start AND m.run_date BETWEEN ar.range_start AND ar.range_end LEFT JOIN codes_in_range cr ON cr.campaign_id = ar.campaign_id AND cr.channel = ar.channel AND cr.week_start = ar.week_start AND cr.range_start = ar.range_start GROUP BY ar.campaign_id, ar.channel, ar.os, ar.week_start, ar.range_start, cr.coupon_code ), coupon_charges AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, customer_id, order_name, order_timestamp::date AS charged_date, COUNT(line_item_id) AS quantity, SUM(gross_sales) AS total_sales, SUM(slashed_discount) AS total_sl_discount, SUM(discount) AS total_discount, MAX(discount_code) AS discount_code FROM SNITCH_DB.MAPLEMONK.FACT_ITEMS_SNITCH f JOIN coupon_codes_unique u ON UPPER(f.discount_code) = u.coupon_code GROUP BY 1,2,3,4 ), coupon_usage AS ( SELECT DISTINCT campaign_id, run_date, UPPER(coupon_code) AS coupon_code FROM coupon_codes WHERE coupon_code IS NOT NULL ), coupon_owner_per_order AS ( SELECT cc.order_name, cc.charged_date, cc.total_sales, cc.discount_code, cu.campaign_id, cu.run_date, ROW_NUMBER() OVER ( PARTITION BY cc.order_name ORDER BY cu.run_date DESC, cu.campaign_id ) AS rn FROM coupon_charges cc JOIN coupon_usage cu ON UPPER(cc.discount_code) = cu.coupon_code AND cu.run_date <= cc.charged_date ), coupon_attributed_orders AS ( SELECT order_name, charged_date, total_sales, discount_code, campaign_id FROM coupon_owner_per_order WHERE UPPER(discount_code) NOT IN (\'APP10\', \'XDAY\') and rn = 1 ), coupon_by_bucket AS ( SELECT ar.campaign_id, ar.channel, ar.range_start AS correct_run_date, COUNT(DISTINCT cao.order_name) AS coupon_orders, SUM(cao.total_sales) AS coupon_revenue FROM coupon_attributed_orders cao JOIN anchor_ranges ar ON ar.campaign_id = cao.campaign_id GROUP BY 1,2,3 ), clicks_charges AS ( SELECT TRY_TO_NUMBER(c_id) AS campaign_id, CASE WHEN LOWER(campaign_channel)=\'push\' THEN \'Push Notification\' ELSE campaign_channel END AS channel, click_date, order_name, total_sales FROM ct_click_charge ), clicks_charges_dedup AS ( SELECT * FROM ( SELECT campaign_id, channel, click_date, order_name, total_sales, ROW_NUMBER() OVER (PARTITION BY campaign_id, channel, order_name ORDER BY click_date DESC) AS rn FROM clicks_charges ) WHERE rn = 1 ), clicks_charges_dedup_no_coupon AS ( SELECT ccd.* FROM clicks_charges_dedup ccd LEFT JOIN coupon_attributed_orders cao ON cao.order_name = ccd.order_name WHERE cao.order_name IS NULL ), charges_attributed AS ( SELECT ar.campaign_id, ar.channel, ar.range_start AS correct_run_date, ccd.order_name, ccd.total_sales FROM anchor_ranges ar JOIN clicks_charges_dedup_no_coupon ccd ON ccd.campaign_id = ar.campaign_id AND ccd.channel = ar.channel AND ccd.click_date BETWEEN ar.range_start AND ar.range_end ) SELECT cbt.campaign_id, cbt.channel, cbt.os, cbt.campaign_name, cbt.details, cbt.correct_run_date AS run_date, cbt.labels, clc.label_1, clc.label_2, clc.label_3, clc.label_4, clc.label_5, cbt.total_sents, cbt.total_deliveries, cbt.total_views, cbt.total_clicks, cbt.coupon_code, CASE WHEN cbt.channel = \'Push Notification\' THEN ROUND(cbt.total_clicks/NULLIF(cbt.total_sents,0),2) WHEN cbt.channel = \'Sms\' THEN ROUND(cbt.total_clicks/NULLIF(cbt.total_deliveries,0),2) WHEN cbt.channel = \'WhatsApp\' THEN ROUND(cbt.total_clicks/NULLIF(cbt.total_views,0),2) WHEN cbt.channel = \'Email\' THEN ROUND(cbt.total_clicks/NULLIF(cbt.total_sents,0),2) ELSE 0 END AS ctr, COALESCE(MAX(cbb.coupon_orders), 0) AS coupon_orders, COALESCE(MAX(cbb.coupon_revenue), 0) AS coupon_revenue, COALESCE(COUNT(DISTINCT ca.order_name), 0) + COALESCE(MAX(cbb.coupon_orders), 0) AS total_orders, CASE WHEN cbt.channel = \'Sms\' AND cbt.correct_run_date BETWEEN \'2025-09-13\' AND \'2025-09-30\' THEN COALESCE(MAX(cbb.coupon_revenue), 0) ELSE COALESCE(SUM(ca.total_sales), 0) + COALESCE(MAX(cbb.coupon_revenue), 0) END AS attributed_revenue, CASE WHEN cbt.channel = \'Push Notification\' THEN 0 WHEN cbt.channel = \'Sms\' AND cbt.correct_run_date < \'2025-09-01\' THEN cbt.total_deliveries * 0.10 WHEN cbt.channel = \'Sms\' THEN cbt.total_deliveries * 0.095 WHEN cbt.channel = \'WhatsApp\' AND cbt.correct_run_date < \'2025-09-01\' THEN cbt.total_deliveries * 0.71 WHEN cbt.channel = \'WhatsApp\' THEN cbt.total_deliveries * 0.69 ELSE 0 END AS spends, ROUND( ( CASE WHEN cbt.channel = \'Sms\' AND cbt.correct_run_date BETWEEN \'2025-09-13\' AND \'2025-09-30\' THEN COALESCE(MAX(cbb.coupon_revenue), 0) ELSE COALESCE(SUM(ca.total_sales), 0) + COALESCE(MAX(cbb.coupon_revenue), 0) END ) / NULLIF( CASE WHEN cbt.channel = \'Push Notification\' THEN 0 WHEN cbt.channel = \'Sms\' THEN cbt.total_deliveries * 0.10 WHEN cbt.channel = \'WhatsApp\' THEN cbt.total_deliveries * 0.71 ELSE 0 END, 0 ), 2 ) AS roas FROM campaign_bucket_totals cbt LEFT JOIN charges_attributed ca ON ca.campaign_id = cbt.campaign_id AND ca.channel = cbt.channel AND ca.correct_run_date = cbt.correct_run_date LEFT JOIN coupon_by_bucket cbb ON cbb.campaign_id = cbt.campaign_id AND cbb.channel = cbt.channel AND cbb.correct_run_date = cbt.correct_run_date LEFT JOIN campaign_labels_cleaned clc ON clc.campaign_id = cbt.campaign_id AND clc.run_date = cbt.correct_run_date WHERE labels NOT ILIKE \'%offline%\' GROUP BY cbt.campaign_id, cbt.channel, cbt.os, cbt.campaign_name, cbt.details, clc.label_1, clc.label_2, clc.label_3, clc.label_4, clc.label_5, cbt.correct_run_date, cbt.total_sents, cbt.total_views, cbt.total_clicks, cbt.total_deliveries, cbt.labels, cbt.coupon_code ORDER BY cbt.correct_run_date DESC, cbt.campaign_id, cbt.channel ); CREATE OR REPLACE TABLE journey_reports_summary AS ( WITH journey_base AS ( SELECT TRY_TO_NUMBER(j.journey_id) AS journey_id, j.journey_name, TRY_TO_NUMBER(j.node_id) AS node_id, j.node_type, CASE WHEN LOWER(j.channel_segment_controller_type) IN (\'push\',\'push notification\') THEN \'Push Notification\' WHEN LOWER(j.channel_segment_controller_type) = \'sms\' THEN \'Sms\' WHEN LOWER(j.channel_segment_controller_type) = \'whatsapp\' THEN \'WhatsApp\' WHEN LOWER(j.channel_segment_controller_type) = \'email\' THEN \'Email\' END AS channel, COALESCE( TRY_TO_TIMESTAMP_NTZ(j.journey_start_time || \', 2025\', \'MON DD, HH24:MI, YYYY\'), TRY_TO_TIMESTAMP_NTZ(j.journey_start_time, \'MON DD, HH24:MI\') )::DATE AS start_date, CASE WHEN j.journey_end_time ILIKE \'%never%\' OR j.journey_end_time IS NULL OR TRIM(j.journey_end_time) = \'\' THEN NULL ELSE COALESCE( TRY_TO_TIMESTAMP_NTZ(j.journey_end_time || \', 2025\', \'MON DD, HH24:MI, YYYY\'), TRY_TO_TIMESTAMP_NTZ(j.journey_end_time, \'MON DD, HH24:MI\') )::DATE END AS end_date, COALESCE(SUM(TRY_TO_NUMBER(j.total_sent)),0) AS total_sents, COALESCE(SUM(TRY_TO_NUMBER(j.total_delivered)),0) AS total_delivered, COALESCE(SUM(TRY_TO_NUMBER(j.total_viewed)),0) AS total_views, COALESCE(SUM(TRY_TO_NUMBER(j.total_clicked)),0) AS total_clicks, j.journey_status, COALESCE(TRY_TO_DATE(j.upload_date,\'DD/MM/YY\'), TRY_TO_DATE(j.upload_date,\'DD-MM-YYYY\')) AS run_date FROM ct_journey_reports j WHERE TRY_TO_NUMBER(j.journey_id) IN (85,112,114,115,117,118,119,120,122,127,131,132,133,143) GROUP BY 1,2,3,4,5,6,7,12,13 UNION ALL SELECT TRY_TO_NUMBER(j.journey_id) AS journey_id, j.journey_name, TRY_TO_NUMBER(j.node_id) AS node_id, j.node_type, CASE WHEN LOWER(j.channel_segment_controller_type) IN (\'push\',\'push notification\') THEN \'Push Notification\' WHEN LOWER(j.channel_segment_controller_type) = \'sms\' THEN \'Sms\' WHEN LOWER(j.channel_segment_controller_type) = \'whatsapp\' THEN \'WhatsApp\' WHEN LOWER(j.channel_segment_controller_type) = \'email\' THEN \'Email\' END AS channel, COALESCE( TRY_TO_TIMESTAMP_NTZ(j.journey_start_time || \', 2025\', \'MON DD, HH24:MI, YYYY\'), TRY_TO_TIMESTAMP_NTZ(j.journey_start_time, \'MON DD, HH24:MI\') )::DATE AS start_date, CASE WHEN j.journey_end_time ILIKE \'%never%\' OR j.journey_end_time IS NULL OR TRIM(j.journey_end_time) = \'\' THEN NULL ELSE COALESCE( TRY_TO_TIMESTAMP_NTZ(j.journey_end_time || \', 2025\', \'MON DD, HH24:MI, YYYY\'), TRY_TO_TIMESTAMP_NTZ(j.journey_end_time, \'MON DD, HH24:MI\') )::DATE END AS end_date, COALESCE(SUM(TRY_TO_NUMBER(j.total_sent)),0) AS total_sents, COALESCE(SUM(TRY_TO_NUMBER(j.total_delivered)),0) AS total_delivered, COALESCE(SUM(TRY_TO_NUMBER(j.total_viewed)),0) AS total_views, COALESCE(SUM(TRY_TO_NUMBER(j.total_clicked)),0) AS total_clicks, j.version_status AS journey_status, COALESCE(TRY_TO_DATE(j.upload_date,\'DD/MM/YY\'), TRY_TO_DATE(j.upload_date,\'DD-MM-YYYY\'),TRY_TO_DATE(j.upload_date,\'YYYY-MM-DD\')) AS run_date FROM ct_journey_reports_1 j WHERE TRY_TO_NUMBER(j.journey_id) IN (85,112,114,115,117,118,119,120,122,127,131,132,133,143) GROUP BY 1,2,3,4,5,6,7,12,13 ), journey_campaign AS ( SELECT TRY_TO_NUMBER(j.journey_id) AS journey_id, TRY_TO_NUMBER(j.node_id) AS node_id, TRY_TO_NUMBER(TRIM(tok.value)) AS campaign_id, CASE WHEN LOWER(j.channel_segment_controller_type) IN (\'push\',\'push notification\') THEN \'Push Notification\' WHEN LOWER(j.channel_segment_controller_type) = \'sms\' THEN \'Sms\' WHEN LOWER(j.channel_segment_controller_type) = \'whatsapp\' THEN \'WhatsApp\' WHEN LOWER(j.channel_segment_controller_type) = \'email\' THEN \'Email\' END AS channel, COALESCE(TRY_TO_DATE(j.upload_date,\'DD/MM/YY\'), TRY_TO_DATE(j.upload_date,\'DD-MM-YYYY\'),TRY_TO_DATE(j.upload_date,\'YYYY-MM-DD\')) AS run_date FROM ct_journey_reports j, TABLE(SPLIT_TO_TABLE(REGEXP_REPLACE(j.campaign_segment_controller_id, \'\\s*\\|\\s*\', \',\'), \',\')) tok WHERE TRY_TO_NUMBER(TRIM(tok.value)) IS NOT NULL UNION ALL SELECT TRY_TO_NUMBER(j.journey_id) AS journey_id, TRY_TO_NUMBER(j.node_id) AS node_id, TRY_TO_NUMBER(TRIM(tok.value)) AS campaign_id, CASE WHEN LOWER(j.channel_segment_controller_type) IN (\'push\',\'push notification\') THEN \'Push Notification\' WHEN LOWER(j.channel_segment_controller_type) = \'sms\' THEN \'Sms\' WHEN LOWER(j.channel_segment_controller_type) = \'whatsapp\' THEN \'WhatsApp\' WHEN LOWER(j.channel_segment_controller_type) = \'email\' THEN \'Email\' END AS channel, COALESCE(TRY_TO_DATE(j.upload_date,\'DD/MM/YY\'), TRY_TO_DATE(j.upload_date,\'DD-MM-YYYY\'),TRY_TO_DATE(j.upload_date,\'YYYY-MM-DD\')) AS run_date FROM ct_journey_reports_1 j, TABLE(SPLIT_TO_TABLE(REGEXP_REPLACE(j.campaign_segment_controller_id, \'\\s*\\|\\s*\', \',\'), \',\')) tok WHERE TRY_TO_NUMBER(TRIM(tok.value)) IS NOT NULL ), clicks_charges AS ( SELECT TRY_TO_NUMBER(C_ID) AS campaign_id, CASE WHEN LOWER(CAMPAIGN_CHANNEL) = \'push\' THEN \'Push Notification\' ELSE CAMPAIGN_CHANNEL END AS channel, CLICK_DATE AS click_date, ORDER_NAME, TOTAL_SALES FROM ct_click_charge WHERE LENGTH(C_ID) IN (4,5) ), charges_attributed AS ( SELECT jc.journey_id, jc.node_id, jc.campaign_id, jc.channel, jc.run_date, cc.order_name, cc.total_sales FROM journey_campaign jc JOIN clicks_charges cc ON cc.campaign_id = jc.campaign_id AND (cc.channel = jc.channel OR jc.channel IS NULL) AND cc.click_date = jc.run_date ), journey_click_summary AS ( SELECT journey_id, node_id, channel, run_date, COUNT(DISTINCT order_name) AS total_orders, SUM(total_sales) AS attributed_revenue FROM charges_attributed GROUP BY 1,2,3,4 ) SELECT j.journey_id, j.journey_name, j.node_id, j.channel, j.start_date, j.run_date, j.total_sents, j.total_delivered, j.total_views, j.total_clicks, j.journey_status, ROUND( CASE WHEN j.channel = \'Push Notification\' THEN j.total_clicks/NULLIF(j.total_sents,0) WHEN j.channel = \'Sms\' THEN j.total_clicks/NULLIF(j.total_sents,0) WHEN j.channel = \'WhatsApp\' THEN j.total_clicks/NULLIF(j.total_views,0) WHEN j.channel = \'Email\' THEN j.total_clicks/NULLIF(j.total_sents,0) ELSE 0 END, 2 ) AS CTR, COALESCE(ca.total_orders, 0) AS total_orders, COALESCE(ca.attributed_revenue, 0) AS attributed_revenue, CASE WHEN j.channel = \'Push Notification\' THEN 0 WHEN j.channel = \'Sms\' THEN j.total_delivered * 0.10 WHEN j.channel = \'WhatsApp\' THEN j.total_delivered * 0.71 ELSE 0 END AS spends, ROUND( COALESCE(ca.attributed_revenue, 0) / NULLIF( CASE WHEN j.channel = \'Push Notification\' THEN 0 WHEN j.channel = \'Sms\' THEN j.total_delivered * 0.10 WHEN j.channel = \'WhatsApp\' THEN j.total_delivered * 0.71 ELSE 0 END, 0 ), 2 ) AS ROAS FROM journey_base j LEFT JOIN journey_click_summary ca ON j.journey_id = ca.journey_id AND j.node_id = ca.node_id AND j.channel = ca.channel AND j.run_date = ca.run_date ORDER BY j.journey_id, j.node_id, j.channel, j.start_date ); CREATE OR REPLACE TABLE daily_retention_revenue AS ( WITH CTE AS ( SELECT order_timestamp::date AS run_date, SUM(gross_sales) as revenue FROM fact_items_snitch WHERE order_timestamp::date >= \'2025-03-01\' GROUP BY 1 ), push_camp_data AS ( SELECT run_date, SUM(ATTRIBUTED_REVENUE) As Push_camp_rev, SUM(Spends) AS Push_camp_spends FROM CAMPAIGN_REPORTS_SUMMARY WHERE CHANNEL = \'Push Notification\' GROUP BY 1 ), push_jour_data AS ( SELECT run_date, SUM(attributed_revenue) AS push_jour_rev, SUM(Spends) AS push_jour_spends FROM JOURNEY_REPORTS_SUMMARY WHERE channel = \'Push Notification\' GROUP BY 1 ), SMS_camp_data AS ( SELECT run_date, SUM(ATTRIBUTED_REVENUE) As sms_camp_rev, SUM(Spends) AS sms_camp_spends FROM CAMPAIGN_REPORTS_SUMMARY WHERE CHANNEL = \'Sms\' GROUP BY 1 ), SMS_jour_data AS ( SELECT run_date, SUM(attributed_revenue) AS sms_jour_rev, SUM(Spends) AS sms_jour_spends FROM JOURNEY_REPORTS_SUMMARY WHERE channel = \'Sms\' GROUP BY 1 ), WA_camp_data AS ( SELECT run_date, SUM(ATTRIBUTED_REVENUE) As wa_camp_rev, SUM(Spends) AS wa_camp_spends FROM CAMPAIGN_REPORTS_SUMMARY WHERE CHANNEL = \'WhatsApp\' GROUP BY 1 ), WA_jour_data AS ( SELECT run_date, SUM(attributed_revenue) AS wa_jour_rev, SUM(Spends) AS wa_jour_spends FROM JOURNEY_REPORTS_SUMMARY WHERE channel = \'WhatsApp\' GROUP BY 1 ), email_camp_data AS ( SELECT run_date, SUM(ATTRIBUTED_REVENUE) As email_camp_rev, SUM(Spends) AS email_camp_spends FROM CAMPAIGN_REPORTS_SUMMARY WHERE CHANNEL = \'Email\' GROUP BY 1 ), email_jour_data AS ( SELECT run_date, SUM(attributed_revenue) AS email_jour_rev, SUM(Spends) AS email_jour_spends FROM JOURNEY_REPORTS_SUMMARY WHERE channel = \'email\' GROUP BY 1 ) SELECT a.*, Coalesce(b.push_camp_rev,0) as push_camp_rev, coalesce(x.push_jour_rev,0) as push_jour_rev, coalesce(c.sms_camp_rev,0) as sms_camp_rev, coalesce(c.sms_camp_spends,0) as sms_camp_spends, coalesce(y.sms_jour_rev,0) as sms_jour_rev, coalesce(y.sms_jour_spends,0) as sms_jour_spends, coalesce(d.wa_camp_rev,0) as wa_camp_rev, coalesce(d.wa_camp_spends,0) as wa_camp_spends, coalesce(z.wa_jour_rev,0) as wa_jour_rev, coalesce(z.wa_jour_spends,0) as wa_jour_spends, coalesce(e.email_camp_rev,0) as email_camp_rev, coalesce(w.email_jour_rev,0) as email_jour_rev FROM CTE a LEFT JOIN push_camp_data b on a.run_date = b.run_date LEFT JOIN push_jour_data x on a.run_date = x.run_date LEFT JOIN sms_camp_data c on a.run_date = c.run_date LEFT JOIN sms_jour_data y on a.run_date = y.run_date LEFT JOIN wa_camp_data d on a.run_date = d.run_date LEFT JOIN wa_jour_data z on a.run_date = z.run_date LEFT JOIN email_camp_data e on a.run_date = e.run_date LEFT JOIN email_jour_data w on a.run_date = w.run_date );",
                    "transaction": true
                }
            ) }}
